234	    public void saveOwner(Owner owner) throws DataAccessException {
235	        if (owner.isNew() && owner.getCustomerCode() == null) {
236	            owner.setCustomerCode(generateCustomerCode(owner));
237	        }
238	        if (owner.isNew() && owner.getNamesakeCount() == null) {
239	            owner.setNamesakeCount(countNamesakes(owner));
240	        }
241	        if (owner.isNew() && owner.getHouseholdMemberCount() == null) {
242	            owner.setHouseholdMemberCount(countHouseholdMembers(owner));
243	        }
244	        ownerRepository.save(owner);
245	
246	    }
