248	    /**
249	     * Count the members of the new owner's household after this create: the existing owners
250	     * that share the given owner's last name and address (compared case-insensitively with
251	     * collapsed whitespace, the same normalization used to derive the household identifier)
252	     * plus the owner being created. Invoked before the new owner is persisted.
253	     */
254	    private int countHouseholdMembers(Owner owner) {
255	        String normalizedLastName = normalizeHouseholdField(owner.getLastName());
256	        String normalizedAddress = normalizeHouseholdField(owner.getAddress());
257	        long existing = ownerRepository.findAll().stream()
258	            .filter(other -> normalizeHouseholdField(other.getLastName()).equals(normalizedLastName)
259	                && normalizeHouseholdField(other.getAddress()).equals(normalizedAddress))
260	            .count();
261	        return (int) existing + 1;
262	    }
263	
264	    /**
265	     * Collapses surrounding and internal whitespace and lower-cases a value so household fields
266	     * can be compared case-insensitively with collapsed whitespace. A {@code null} value
267	     * normalizes to the empty string.
268	     */
269	    private String normalizeHouseholdField(String value) {
270	        if (value == null) {
271	            return "";
272	        }
273	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
274	    }
275	
276	    /**
277	     * Count the existing owners that share the given owner's first name and last name,
278	     * compared case-insensitively. Invoked before the new owner is persisted, so the
279	     * result is the number of namesakes that existed at the time of creation.
280	     */
281	    private int countNamesakes(Owner owner) {
282	        String firstName = owner.getFirstName();
283	        String lastName = owner.getLastName();
284	        if (firstName == null || lastName == null) {
285	            return 0;
286	        }
287	        return (int) ownerRepository.findAll().stream()
288	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
289	                && lastName.equalsIgnoreCase(existing.getLastName()))
290	            .count();
291	    }
292	
293	    /**
294	     * Build the owner's customer code in the form '<CITY3>-<LAST3>-<NNNN>' where CITY3 is
295	     * the upper-cased first three letters of the owner's city, LAST3 is the upper-cased
296	     * first three letters of the owner's last name and NNNN is a per-city 4-digit
297	     * zero-padded sequence equal to one more than the number of owners already in that city.
298	     */
299	    private String generateCustomerCode(Owner owner) {
300	        String city = owner.getCity();
301	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
302	        String lastName = owner.getLastName();
303	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
304	        int sequence = (int) ownerRepository.findAll().stream()
305	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
306	            .count() + 1;
307	        return String.format("%s-%s-%04d", city3, last3, sequence);
308	    }
309	
