328	    private <T> T findEntityById(Supplier<T> supplier) {
329	        try {
330	            return supplier.get();
331	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
332	            // Just ignore not found exceptions for Jdbc/Jpa realization
333	            return null;
334	        }
335	    }
