37	    OwnerDto toOwnerDto(Owner owner);
38	
39	    /**
40	     * Derives an owner's preferred contact channel: {@code "EMAIL"} when the owner has a non-blank
41	     * email, otherwise {@code "PHONE"}.
42	     *
43	     * @param owner the owner to derive the contact preference for
44	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
45	     */
46	    default String contactPreference(Owner owner) {
47	        String email = owner.getEmail();
48	        return (email != null && !email.isBlank()) ? "EMAIL" : "PHONE";
49	    }
50	
51	    /**
52	     * Derives an owner's locality, preferring the postcode over the city. The postcode is looked up
53	     * against the canonical region ranges first ({@code NSW 2000-2099}, {@code VIC 3000-3099},
54	     * {@code QLD 4000-4099}); only when the postcode is absent or falls in no known range does the
55	     * derivation fall back to the fixed city-to-region table ({@code Sydney->NSW},
56	     * {@code Melbourne->VIC}, {@code Brisbane->QLD}). This returns the same region for known cities
57	     * but disambiguates cities that share a name. The result is {@code "UNKNOWN"} when neither the
58	     * postcode nor the city resolves to a region.
59	     *
60	     * @param owner the owner to derive the locality for
61	     * @return the canonical region string, or {@code "UNKNOWN"}
62	     */
63	    default String locality(Owner owner) {
64	        String region = regionFromPostcode(owner.getPostcode());
65	        if (region != null) {
66	            return region;
67	        }
68	        return regionFromCity(owner.getCity());
69	    }
70	
71	    /**
72	     * Looks up the canonical region for a postcode by its range ({@code NSW 2000-2099},
73	     * {@code VIC 3000-3099}, {@code QLD 4000-4099}).
74	     *
75	     * @param postcode the owner's postcode, may be {@code null}
76	     * @return the region, or {@code null} when the postcode is absent, non-numeric or in no range
77	     */
78	    private String regionFromPostcode(String postcode) {
79	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
80	            return null;
81	        }
82	        int value = Integer.parseInt(postcode);
83	        if (value >= 2000 && value <= 2099) {
84	            return "NSW";
85	        }
86	        if (value >= 3000 && value <= 3099) {
87	            return "VIC";
88	        }
89	        if (value >= 4000 && value <= 4099) {
90	            return "QLD";
91	        }
92	        return null;
93	    }
94	
95	    /**
96	     * Looks up the canonical region for a city using the fixed city-to-region table.
97	     *
98	     * @param city the owner's city, may be {@code null}
99	     * @return the region, or {@code "UNKNOWN"} when the city is absent or not in the table
100	     */
101	    private String regionFromCity(String city) {
102	        if (city == null) {
103	            return "UNKNOWN";
104	        }
105	        return switch (city) {
106	            case "Sydney" -> "NSW";
107	            case "Melbourne" -> "VIC";
108	            case "Brisbane" -> "QLD";
109	            default -> "UNKNOWN";
110	        };
111	    }
112	
113	    /**
114	     * Derives an owner's numeric membership level, fixed at creation. Starts at {@code 1}, plus
115	     * {@code 1} when an email is present (non-blank), plus {@code 1} when the owner's namesake count
116	     * is {@code 0}, capped at {@code 3} (level {@code 4} is reserved for tenure).
117	     *
118	     * @param owner the owner to derive the membership level for
119	     * @return the membership level, between {@code 1} and {@code 3}
120	     */
121	    default Integer membershipLevel(Owner owner) {
122	        int level = 1;
123	        String email = owner.getEmail();
124	        if (email != null && !email.isBlank()) {
125	            level++;
126	        }
127	        Integer namesakeCount = owner.getNamesakeCount();
128	        if (namesakeCount != null && namesakeCount == 0) {
129	            level++;
130	        }
131	        return Math.min(level, 3);
132	    }
133	
134	    /**
135	     * Derives an owner's membership number, formatted {@code <customerCode>-M<YY>} where
136	     * {@code <customerCode>} is the owner's customer code and {@code YY} is the last two digits
137	     * (zero-padded) of the owner's registration date year (e.g. {@code LON-SMI-0007-M26}).
138	     *
139	     * @param owner the owner to derive the membership number for
140	     * @return the formatted membership number
141	     */
142	    default String membershipNumber(Owner owner) {
143	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
144	        return owner.getCustomerCode() + "-M" + yy;
145	    }
146	
147	    /**
148	     * Derives an owner's check digit: a single Luhn check digit ({@code 0}-{@code 9}) computed over
149	     * the digits contained in the owner's customer code. Non-digit characters in the customer code
150	     * are ignored.
151	     *
152	     * @param owner the owner to derive the check digit for
153	     * @return the Luhn check digit, between {@code 0} and {@code 9}
154	     */
155	    default Integer checkDigit(Owner owner) {
156	        String code = owner.getCustomerCode();
157	        int sum = 0;
158	        boolean dbl = true;
159	        for (int i = code.length() - 1; i >= 0; i--) {
160	            char c = code.charAt(i);
161	            if (c < '0' || c > '9') {
162	                continue;
163	            }
164	            int d = c - '0';
165	            if (dbl) {
166	                d *= 2;
167	                if (d > 9) {
168	                    d -= 9;
169	                }
170	            }
171	            sum += d;
172	            dbl = !dbl;
173	        }
174	        return (10 - (sum % 10)) % 10;
175	    }
176	
177	    /**
178	     * Derives an owner's household identifier: a stable value shared by every owner with the same
179	     * last name and address (compared case-insensitively with collapsed whitespace). Because it is
180	     * derived deterministically from those fields, owners created via the {@code sharesHousehold}
181	     * flag - which by definition have a matching last name and address - receive the same value.
182	     *
183	     * @param owner the owner to derive the household identifier for
184	     * @return a {@code HH-} prefixed identifier, never blank
185	     */
186	    default String householdId(Owner owner) {
187	        String key = normalizeHouseholdField(owner.getLastName()) + ' '
188	            + normalizeHouseholdField(owner.getAddress());
189	        try {
190	            byte[] digest = MessageDigest.getInstance("SHA-256")
191	                .digest(key.getBytes(StandardCharsets.UTF_8));
192	            StringBuilder sb = new StringBuilder("HH-");
193	            for (int i = 0; i < 6; i++) {
194	                sb.append(String.format("%02X", digest[i]));
195	            }
196	            return sb.toString();
197	        }
198	        catch (NoSuchAlgorithmException ex) {
199	            throw new IllegalStateException("SHA-256 not available", ex);
200	        }
201	    }
202	
203	    /**
204	     * Derives an owner's identity key, into which all duplicate detection is consolidated. The key
205	     * is {@code <normalizedTelephone>|<email or empty>|<householdId>}: the owner's (already E.164
206	     * normalized) telephone, its (already lower-cased) email or the empty string when none is held,
207	     * and its {@link #householdId(Owner) household id}. Two owners are duplicates only when their
208	     * whole identity keys are equal; because the telephone is part of the key, household members with
209	     * different telephones have different keys.
210	     *
211	     * @param owner the owner to derive the identity key for
212	     * @return the {@code telephone|email|householdId} identity key
213	     */
214	    default String identityKey(Owner owner) {
215	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
216	        String email = owner.getEmail() == null ? "" : owner.getEmail();
217	        return telephone + '|' + email + '|' + householdId(owner);
218	    }
