226	     * conversion and apply it to unrelated String properties (last name, address, ...).
227	     */
228	    private String normalizeHouseholdField(String value) {
229	        if (value == null) {
230	            return "";
231	        }
232	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
233	    }
