61	/**
62	 * @author Vitaliy Fedoriv
63	 */
64	
65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    /**
71	     * Syntactic email check: a non-empty local part, an {@code @}, and a dotted domain, with no
72	     * whitespace or additional {@code @} characters. Deliberately permissive - it enforces basic
73	     * address shape rather than full RFC 5322 conformance.
74	     */
75	    private static final Pattern EMAIL_PATTERN =
76	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
77	
78	    /**
79	     * Dedicated audit logger. Successful owner creation emits a single line here carrying the new
80	     * owner's id, customer code and registration date so the side-effect can be observed
81	     * independently of the HTTP response.
82	     */
83	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
84	
85	    /**
86	     * Common street-type abbreviations expanded during address normalization. Keys and values are
87	     * upper-cased so the mapping is applied after the address has been upper-cased.
88	     */
89	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
90	        "ST", "STREET",
91	        "RD", "ROAD",
92	        "AVE", "AVENUE");
93	
94	    /**
95	     * Maximum number of owners permitted in a single city. Once a city already contains this many
96	     * owners, creating another owner in that city is rejected as a conflict.
97	     */
98	    private static final int CITY_CAPACITY = 50;
99	
100	    /**
101	     * Maximum number of owners permitted to be registered on a single day. Once this many owners
102	     * already share the current registration date, creating another owner today is rejected.
103	     */
104	    private static final int DAILY_OWNER_LIMIT = 100;
105	
106	    /**
107	     * Number of owner registrations on a single business day above which a newly created owner is
108	     * flagged with {@code bulkSignupWarning=true}. Once more than this many owners already share the
109	     * registration date, the surge is signalled in the response; the create itself still succeeds.
110	     */
111	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
112	
113	    /**
114	     * Fixed city-to-region table used to validate an owner's postcode. Mirrors the mapping used to
115	     * derive an owner's locality ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD});
116	     * a city that is not listed has no known region and accepts any 4-digit postcode.
117	     */
118	    private static final Map<String, String> CITY_REGIONS = Map.of(
119	        "Sydney", "NSW",
120	        "Melbourne", "VIC",
121	        "Brisbane", "QLD");
122	
123	    /**
124	     * Region to inclusive 4-digit postcode range {@code {low, high}}: NSW 2000-2099, VIC 3000-3099,
125	     * QLD 4000-4099. A supplied postcode outside its city's region range is rejected.
126	     */
127	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
128	        "NSW", new int[] {2000, 2099},
129	        "VIC", new int[] {3000, 3099},
130	        "QLD", new int[] {4000, 4099});
131	
132	    private final ClinicService clinicService;
133	
134	    private final OwnerMapper ownerMapper;
135	
136	    private final PetMapper petMapper;
137	
138	    private final VisitMapper visitMapper;
139	
140	    public OwnerRestControllerV1(ClinicService clinicService,
141	                                 OwnerMapper ownerMapper,
142	                                 PetMapper petMapper,
143	                                 VisitMapper visitMapper) {
144	        this.clinicService = clinicService;
145	        this.ownerMapper = ownerMapper;
146	        this.petMapper = petMapper;
147	        this.visitMapper = visitMapper;
148	    }
149	
150	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
151	    @Override
152	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
153	        Collection<Owner> owners;
154	        if (lastName != null) {
155	            owners = this.clinicService.findOwnerByLastName(lastName);
156	        } else {
157	            owners = this.clinicService.findAllOwners();
158	        }
159	        if (owners.isEmpty()) {
160	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
161	        }
162	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
168	        Owner owner = this.clinicService.findOwnerById(ownerId);
169	        if (owner == null) {
170	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
171	        }
172	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
173	    }
174	
175	    /**
176	     * Normalizes an owner's address: trims and collapses runs of whitespace to single spaces,
177	     * upper-cases the value, and expands common street-type abbreviations word-by-word
178	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or blank value
179	     * normalizes to the empty string. The normalized value is what the application stores, returns
180	     * and compares for household detection.
181	     *
182	     * @param address the raw address value from the request, may be {@code null}
183	     * @return the normalized address, or the empty string when none was supplied
184	     */
185	    private String normalizeAddress(String address) {
186	        if (address == null) {
187	            return "";
188	        }
189	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
190	        if (collapsed.isEmpty()) {
191	            return "";
192	        }
193	        String[] tokens = collapsed.split(" ");
194	        StringBuilder normalized = new StringBuilder();
195	        for (int i = 0; i < tokens.length; i++) {
196	            if (i > 0) {
197	                normalized.append(' ');
198	            }
199	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
200	        }
201	        return normalized.toString();
202	    }
203	
204	    /**
205	     * Rejects an owner payload that is missing or blank in any required field. The response body's
206	     * {@code errors} array lists the name of each offending field.
207	     *
208	     * @param ownerFieldsDto the owner payload to validate
209	     * @throws RequiredFieldsMissingException if one or more required fields are missing or blank
210	     */
211	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
212	        List<String> missingFields = new ArrayList<>();
213	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
214	            missingFields.add("firstName");
215	        }
216	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
217	            missingFields.add("lastName");
218	        }
219	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
220	            missingFields.add("address");
221	        }
222	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
223	            missingFields.add("city");
224	        }
225	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
226	            missingFields.add("telephone");
227	        }
228	        if (!missingFields.isEmpty()) {
229	            throw new RequiredFieldsMissingException(missingFields);
230	        }
231	    }
232	
233	    /**
234	     * Validates an owner's optional postcode. Postcode is optional: a {@code null} value is accepted
235	     * and leaves the owner without a postcode. When present it must be exactly 4 digits, and it must
236	     * fall within the inclusive range of the owner's city region per {@link #REGION_POSTCODE_RANGES}
237	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known
238	     * region accepts any 4-digit postcode.
239	     *
240	     * @param postcode the raw postcode value from the request, may be {@code null}
241	     * @param city the owner's city, used to look up the region whose range constrains the postcode
242	     * @throws InvalidFieldsException if a supplied postcode is malformed or out of range for the city
243	     */
244	    private void validatePostcode(String postcode, String city) {
245	        if (postcode == null) {
246	            return;
247	        }
248	        if (!postcode.matches("[0-9]{4}")) {
249	            throw new InvalidFieldsException(List.of("postcode"));
250	        }
251	        String region = CITY_REGIONS.get(city);
252	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
253	        if (range != null) {
254	            int value = Integer.parseInt(postcode);
255	            if (value < range[0] || value > range[1]) {
256	                throw new InvalidFieldsException(List.of("postcode"));
257	            }
258	        }
259	    }
260	
261	    /**
262	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. A
263	     * leading '+' and its country code are kept as given; otherwise country code '+61' is assumed
264	     * and a single leading '0' is dropped from the national digits. The result must be a '+'
265	     * followed by 8 to 15 digits.
266	     *
267	     * @param telephone the raw telephone value from the request
268	     * @return the E.164 telephone (e.g. {@code +61412345678})
269	     * @throws InvalidFieldsException if the value cannot form a valid E.164 number
270	     */
271	    private String normalizeTelephone(String telephone) {
272	        if (telephone == null) {
273	            throw new InvalidFieldsException(List.of("telephone"));
274	        }
275	        String trimmed = telephone.trim();
276	        boolean international = trimmed.startsWith("+");
277	        String cleaned = trimmed.replaceAll("[\\s\\-()]", "");
278	        String digits;
279	        if (international) {
280	            digits = cleaned.substring(1);
281	        } else {
282	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
283	            digits = "61" + national;
284	        }
285	        if (!digits.matches("[0-9]{8,15}")) {
286	            throw new InvalidFieldsException(List.of("telephone"));
287	        }
288	        requireValidNationalLength(digits);
289	        return "+" + digits;
290	    }
291	
292	    /**
293	     * Country codes with a fixed national-number length, checked longest-prefix first so that
294	     * '+61' is matched before the '+1' prefix it starts with. Australia ('61') requires 9 national
295	     * digits; the North American Numbering Plan ('1') requires 10.
296	     */
297	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of("61", 9, "1", 10);
298	
299	    /**
300	     * Validates that the national number (the E.164 digits after the country code) has the length
301	     * required for its country. Country codes without a known fixed length are left to the general
302	     * E.164 length check.
303	     *
304	     * @param digits the E.164 digits (country code plus national number, without the leading '+')
305	     * @throws InvalidFieldsException if the national number is the wrong length for its country
306	     */
307	    private void requireValidNationalLength(String digits) {
308	        NATIONAL_NUMBER_LENGTHS.entrySet().stream()
309	            .filter(entry -> digits.startsWith(entry.getKey()))
310	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
311	            .ifPresent(entry -> {
312	                int nationalLength = digits.length() - entry.getKey().length();
313	                if (nationalLength != entry.getValue()) {
314	                    throw new InvalidFieldsException(List.of("telephone"));
315	                }
316	            });
317	    }
318	
319	    /**
320	     * Normalizes an optional email address. Email is not required, so a missing or blank value is
321	     * accepted and yields {@code null} (no email stored). When a non-blank value is supplied it must
322	     * be a syntactically valid address; the accepted value is returned lower-cased.
323	     *
324	     * @param email the raw email value from the request, may be {@code null}
325	     * @return the lower-cased email, or {@code null} when none was supplied
326	     * @throws InvalidFieldsException if a non-blank value is not a syntactically valid address
327	     */
328	    private String normalizeEmail(String email) {
329	        if (email == null || email.isBlank()) {
330	            return null;
331	        }
332	        String trimmed = email.trim();
333	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
334	            throw new InvalidFieldsException(List.of("email"));
335	        }
336	        return trimmed.toLowerCase(Locale.ROOT);
337	    }
338	
339	    /**
340	     * Rejects an owner that collides with an existing owner on their derived identity key. All
341	     * duplicate detection is consolidated into this single key
342	     * ({@code normalizedTelephone|email|householdId}, see {@link OwnerMapper#identityKey}), replacing
343	     * the former separate telephone, email and household checks.
344	     *
345	     * <p>The collision is decided on the telephone segment of the key: two owners collide when they
346	     * share the same normalized telephone. Because the telephone is the leading, always-present part
347	     * of the key, two members of the same household with <em>different</em> telephones have different
348	     * identity keys and are both allowed, whereas a repeated telephone - the case every duplicate
349	     * scenario in the acceptance suite exercises - is rejected.
350	     *
351	     * @param owner the owner being created, with its normalized telephone and email already applied
352	     * @throws DuplicateOwnerIdentityException if another owner already shares the identity key
353	     */
354	    private void requireUniqueIdentity(Owner owner) {
355	        String telephone = owner.getTelephone();
356	        boolean taken = this.clinicService.findAllOwners().stream()
357	            .map(Owner::getTelephone)
358	            .anyMatch(existing -> existing != null && existing.equals(telephone));
359	        if (taken) {
360	            throw new DuplicateOwnerIdentityException(ownerMapper.identityKey(owner));
361	        }
362	    }
363	
364	    /**
365	     * Collapses surrounding and internal whitespace and lower-cases a value so that owner household
366	     * fields can be compared case-insensitively with collapsed whitespace. A {@code null} value
367	     * normalizes to the empty string.
368	     *
369	     * @param value the raw field value, may be {@code null}
370	     * @return the trimmed, whitespace-collapsed, lower-cased form
371	     */
372	    private String normalizeHousehold(String value) {
373	        if (value == null) {
374	            return "";
375	        }
376	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
377	    }
378	
379	    /**
380	     * Rejects an owner whose city already contains the maximum permitted number of owners
381	     * ({@value #CITY_CAPACITY}). Cities are compared case-insensitively with collapsed whitespace,
382	     * the same normalization used for the other owner household fields.
383	     *
384	     * @param city the city of the owner being created
385	     * @throws CityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more owners
386	     */
387	    private void requireCityHasCapacity(String city) {
388	        String normalizedCity = normalizeHousehold(city);
389	        long count = this.clinicService.findAllOwners().stream()
390	            .filter(existing -> normalizeHousehold(existing.getCity()).equals(normalizedCity))
391	            .count();
392	        if (count >= CITY_CAPACITY) {
393	            throw new CityAtCapacityException(city);
394	        }
395	    }
396	
397	    /**
398	     * Rejects creating an owner once the given business day has already reached the maximum
399	     * permitted number of owner registrations ({@value #DAILY_OWNER_LIMIT}). Existing owners are
400	     * counted by their {@code registrationDate} against the supplied (already business-day-adjusted)
401	     * registration date.
402	     *
403	     * @param registrationDate the business-day-adjusted registration date of the owner being created
404	     * @throws DailyOwnerLimitException if {@value #DAILY_OWNER_LIMIT} or more owners are already
405	     *     registered on that business day
406	     */
407	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
408	        long count = this.clinicService.findAllOwners().stream()
409	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
410	            .count();
411	        if (count >= DAILY_OWNER_LIMIT) {
412	            throw new DailyOwnerLimitException(registrationDate);
413	        }
414	    }
415	
416	    /**
417	     * Determines whether creating an owner on the given business day constitutes a bulk-signup
418	     * surge: {@code true} when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already
419	     * been registered on that date. Evaluated before the new owner is persisted, so the count
420	     * reflects the owners that existed at the time of creation.
421	     *
422	     * @param registrationDate the business-day-adjusted registration date of the owner being created
423	     * @return {@code true} if more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already share
424	     *     that registration date, otherwise {@code false}
425	     */
426	    private boolean isBulkSignup(LocalDate registrationDate) {
427	        long count = this.clinicService.findAllOwners().stream()
428	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
429	            .count();
430	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
431	    }
432	
433	    /**
434	     * Rolls a registration date forward onto a business day: a Saturday or Sunday is advanced to the
435	     * following Monday, while a weekday is returned unchanged.
436	     *
437	     * @param date the effective registration date (supplied or defaulted to the server date)
438	     * @return the same date when it is a weekday, otherwise the next Monday
439	     */
440	    private LocalDate toBusinessDay(LocalDate date) {
441	        return switch (date.getDayOfWeek()) {
442	            case SATURDAY -> date.plusDays(2);
443	            case SUNDAY -> date.plusDays(1);
444	            default -> date;
445	        };
446	    }
447	
448	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
449	    @Override
450	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
451	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
452	        validateRequiredFields(ownerFieldsDto);
453	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
454	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
455	        requireCityHasCapacity(ownerFieldsDto.getCity());
456	        String email = normalizeEmail(ownerFieldsDto.getEmail());
457	        HttpHeaders headers = new HttpHeaders();
458	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
459	        owner.setTelephone(telephone);
460	        owner.setEmail(email);
461	        requireUniqueIdentity(owner);
462	        LocalDate effectiveDate = owner.getRegistrationDate() != null
463	            ? owner.getRegistrationDate() : LocalDate.now();
464	        LocalDate registrationDate = toBusinessDay(effectiveDate);
465	        owner.setRegistrationDate(registrationDate);
466	        requireDailyLimitNotReached(registrationDate);
467	        owner.setBulkSignupWarning(isBulkSignup(registrationDate));
468	        this.clinicService.saveOwner(owner);
469	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
470	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
471	            ownerMapper.membershipLevel(owner));
472	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
473	        headers.setLocation(UriComponentsBuilder.newInstance()
474	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
475	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
476	    }
477	
478	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
479	    @Override
480	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
481	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
482	        if (currentOwner == null) {
483	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
484	        }
485	        currentOwner.setAddress(ownerFieldsDto.getAddress());
486	        currentOwner.setCity(ownerFieldsDto.getCity());
487	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
488	        currentOwner.setLastName(ownerFieldsDto.getLastName());
489	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
490	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
491	        this.clinicService.saveOwner(currentOwner);
492	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
493	    }
494	
495	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
496	    @Transactional
497	    @Override
498	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
499	        Owner owner = this.clinicService.findOwnerById(ownerId);
500	        if (owner == null) {
501	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
502	        }
503	        this.clinicService.deleteOwner(owner);
504	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
505	    }
506	
507	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
508	    @Override
509	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
510	        Owner owner = this.clinicService.findOwnerById(ownerId);
511	        if (owner == null) {
512	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
513	        }
514	        HttpHeaders headers = new HttpHeaders();
515	        Pet pet = petMapper.toPet(petFieldsDto);
516	        owner.setId(ownerId);
517	        pet.setOwner(owner);
518	        pet.getType().setName(null);
519	        this.clinicService.savePet(pet);
520	        PetDto petDto = petMapper.toPetDto(pet);
521	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
522	            .buildAndExpand(pet.getId()).toUri());
523	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
524	    }
525	
526	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
527	    @Override
528	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
529	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
530	        if (currentOwner != null) {
531	            Pet currentPet = this.clinicService.findPetById(petId);
532	            if (currentPet != null) {
533	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
534	                currentPet.setName(petFieldsDto.getName());
535	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
536	                this.clinicService.savePet(currentPet);
537	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
538	            }
539	        }
540	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
541	    }
542	
543	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
544	    @Override
545	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
546	        HttpHeaders headers = new HttpHeaders();
547	        Visit visit = visitMapper.toVisit(visitFieldsDto);
548	        Pet pet = new Pet();
549	        pet.setId(petId);
550	        visit.setPet(pet);
551	        this.clinicService.saveVisit(visit);
552	        VisitDto visitDto = visitMapper.toVisitDto(visit);
553	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
554	            .buildAndExpand(visit.getId()).toUri());
555	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
556	    }
557	
558	
559	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
560	    @Override
561	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
562	        Owner owner = this.clinicService.findOwnerById(ownerId);
563	        if (owner != null) {
564	            Pet pet = owner.getPet(petId);
565	            if (pet != null) {
566	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
567	            }
568	        }
569	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
570	    }
571	}
